style.css:
body, a:hover {
    cursor: auto !important;
}

body {
    font-family: "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 16px;
    font-weight: 400;
    line-height: 24px;
    color: #6f6f6f;
    background-color: #ffffff;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    margin: 0;
}

html, body {
    height: 100%;
}

/* Box-sizing per tutti gli elementi */
* {
    box-sizing: border-box;
}

:root {
    --primary-font-face: 'Source Sans Pro', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    --font-weight-normal: 400;
    --font-weight-bold: 700;
    --font-size-xl: 32px;
    --font-size-l: 22px;
    --font-size-m: 18px;
    --font-size-sm: 16px;
    --font-size-xs: 14px;
    --font-size-xxs: 12px;
    --font-color-primary: var(--ds-neutral-100);
    --line-height-xl: 40px;
    --line-height-l: 28px;
    --line-height-m: 24px;
    --line-height-sm: 22px;
    --line-height-xs: 20px;
    --line-height-xxs: 16px;
    --corner-radius: 8px;
}

:root {
    --ds-neutral-100: #a900ff;
    --ds-neutral-00: #ffffff;
    --ds-base-1-accent: #ff500a;
    --ds-base-2-accent: #5c10ff;
    --ds-base-3-accent: #18a599;
    --ds-base-4-accent: #e81249;
    --ds-base-5-accent: #d67d00;
    --ds-base-6-accent: #00a1b3;
    --ds-base-7-accent: #51a800;
}
